const item = $input.first().json;
const body = item.body || item;
const message = body.message || {};
const functionCall = message.functionCall || (message.toolCalls && message.toolCalls[0] ? message.toolCalls[0].function : {}) || {};
let params = functionCall.parameters || functionCall.arguments || body;

if (typeof params === 'string') {
    try { params = JSON.parse(params); } catch (e) {}
}

let customerPhone = String(params.customer_phone || params.phone || '').trim();
customerPhone = customerPhone.replace(/[^0-9+]/g, '');
if (customerPhone.startsWith('0')) {
    customerPhone = '+49' + customerPhone.substring(1);
} else if (!customerPhone.startsWith('+') && customerPhone.startsWith('49')) {
    customerPhone = '+' + customerPhone;
}

let customerName = String(params.customer_name || 'Unbekannter Anrufer').trim();
let address = String(params.address || 'Großraum Goslar / Harz').trim();
let issueDescription = String(params.issue_description || 'Notdienst-Einsatz').trim();
let urgency = String(params.urgency || 'NOTFALL').toUpperCase();
if (!['NOTFALL', 'DRINGEND', 'STANDARD'].includes(urgency)) {
    urgency = 'NOTFALL';
}

return [{
    json: {
        customer_name: customerName,
        customer_phone: customerPhone,
        address: address,
        issue_description: issueDescription,
        urgency: urgency,
        status: 'NEU'
    }
}];

