const payload = $input.first().json.body || $input.first().json;
const entry = (payload.entry && payload.entry[0]) || {};
const changes = (entry.changes && entry.changes[0]) || {};
const val = changes.value || {};
const messages = val.messages || [];

if (!messages.length) { return []; }

const msg = messages[0];
const msgType = msg.type;
if (msgType !== 'image' && msgType !== 'video') { return []; }

const mediaObj = msg[msgType];
const rawPhone = msg.from || (val.contacts && val.contacts[0] ? val.contacts[0].wa_id : '');
let phoneSuffix = rawPhone.replace(/[^0-9]/g, '');
if (phoneSuffix.length > 8) { phoneSuffix = phoneSuffix.slice(-8); }

return [{
    json: {
        sender_phone: rawPhone,
        phone_suffix: phoneSuffix,
        media_id: mediaObj.id,
        mime_type: mediaObj.mime_type || 'image/jpeg',
        caption: mediaObj.caption || ''
    }
}];

const activeOrderData = $('Find Active Order in Supabase').item.json;
const order = (Array.isArray(activeOrderData) && activeOrderData.length > 0) ? activeOrderData[0] : (activeOrderData && activeOrderData.id ? activeOrderData : null);

if (!order || !order.id) {
    return [{
        json: {
            orderId: null,
            unassigned: true,
            updated_photo_urls: [],
            new_photo_url: null,
            warning: 'No active order found in Supabase for sender'
        }
    }];
}

const mediaMeta = $('Parse Inbound Media').item.json || {};
const orderId = order.id;
const supabaseUrl = $env.SUPABASE_URL || 'https://supabase-project.supabase.co';
const photoUrl = `${supabaseUrl}/storage/v1/object/harzblitz-damage-photos/${orderId}/${mediaMeta.media_id || 'unknown'}.jpg`;

const currentPhotos = Array.isArray(order.photo_urls) ? [...order.photo_urls] : [];
if (photoUrl && !currentPhotos.includes(photoUrl)) {
    currentPhotos.push(photoUrl);
}

return [{
    json: {
        orderId: orderId,
        updated_photo_urls: currentPhotos,
        new_photo_url: photoUrl
    }
}];

const searchResult = $input.first().json;
const orderData = $('Order Erledigt Webhook').first().json.body || $('Order Erledigt Webhook').first().json;
const contacts = searchResult.content || [];

let matchedContactId = null;
if (contacts.length > 0) {
    matchedContactId = contacts[0].id;
}

const fullName = (orderData.customer_name || 'Kunde').trim();
const nameParts = fullName.split(' ');
const firstName = nameParts.length > 1 ? nameParts.slice(0, -1).join(' ') : '';
const lastName = nameParts.length > 1 ? nameParts.slice(-1)[0] : fullName;

const rawAddress = (orderData.address || '').trim();
let street = rawAddress;
let zip = '38640';
let city = 'Goslar';

const zipMatch = rawAddress.match(/(\d{5})\s+([^,]+)/);
if (zipMatch) {
    zip = zipMatch[1];
    city = zipMatch[2].trim();
    street = rawAddress.split(zipMatch[0])[0].replace(/,$/, '').trim();
}

const contactPayload = {
    version: 0,
    roles: { customer: {} },
    person: {
        salutation: 'Herr',
        firstName: firstName || 'Herr',
        lastName: lastName
    },
    phoneNumbers: {
        mobile: [orderData.customer_phone || '+495321000000']
    },
    addresses: {
        billing: [
            {
                street: street || 'Musterstraße 1',
                zip: zip,
                city: city,
                countryCode: 'DE'
            }
        ]
    }
};

return [{
    json: {
        needsCreate: !matchedContactId,
        contactId: matchedContactId,
        contactPayload: contactPayload,
        orderData: orderData
    }
}];

const prevItem = $input.first().json;
const evalNode = $('Evaluate Contact Match').first().json;
const contactId = prevItem.id || evalNode.contactId;
const orderData = evalNode.orderData || {};

const now = new Date();
const todayIso = now.toISOString().split('T')[0] + 'T00:00:00.000+01:00';

const netHours = 142.50;
const netPauschale = 69.00;
const totalNet = 211.50;
const totalTax = 40.19;
const totalGross = 251.69;

const invoicePayload = {
    voucherDate: todayIso,
    voucherStatus: "draft",
    address: {
        contactId: contactId
    },
    title: 'Rechnung (Notdienst-Einsatz)',
    introduction: `Sehr geehrte Damen und Herren,\nfür den Notdienst-Einsatz durch HarzBlitz Notdienst & Gebäudetechnik GmbH am Objekt ${orderData.address || 'vor Ort'} stellen wir Ihnen folgende Positionen in Rechnung:`,
    remark: `HarzBlitz Notdienst-Auftrag ${orderData.id || ''} - Einsatzort: ${orderData.address || 'Großraum Goslar'} - DATEV Erlöskonto 8400 (19% USt) - Freigabe Meister Marc Schneider erforderlich.\nZahlbar rein netto innerhalb von 14 Tagen. Bei Rückfragen: 05321-778890.`,
    lineItems: [
        {
            type: 'custom',
            name: 'Notdienst-Einsatz Rohrreinigung',
            description: `Notdienst-Einsatz vor Ort (${orderData.issue_description || 'Störungsbeseitigung'}), Fachhandwerker-Arbeitszeit 1,5 Std. à 95,00 € zzgl. MwSt.`,
            quantity: 1.5,
            unitName: 'Stunden',
            unitPrice: {
                currency: 'EUR',
                netAmount: 95.00,
                taxRatePercentage: 19
            }
        },
        {
            type: 'custom',
            name: 'Notdienstpauschale',
            description: 'Bereitstellung Einsatzfahrzeug, Notdienst-Ausrüstung und 24/7 Notdienst-Einsatzpauschale',
            quantity: 1,
            unitName: 'Pauschale',
            unitPrice: {
                currency: 'EUR',
                netAmount: 69.00,
                taxRatePercentage: 19
            }
        }
    ],
    totalPrice: {
        currency: 'EUR',
        totalNetAmount: totalNet,
        totalGrossAmount: totalGross,
        totalTaxAmount: totalTax
    },
    taxAmounts: [
        {
            taxRatePercentage: 19,
            taxAmount: totalTax,
            netAmount: totalNet
        }
    ],
    taxConditions: {
        taxType: 'net'
    },
    shippingConditions: {
        shippingDate: todayIso,
        shippingType: 'service'
    }
};

return [{
    json: {
        invoicePayload: invoicePayload,
        orderId: orderData.id,
        contactId: contactId
    }
}];
